// @ts-strict-ignore
import { mapCustomerDisplayApiToCustomerDisplayWeb } from "@/core/helpers/park-food-helper";
import { CustomerDisplayWeb } from "@/core/types/park-food-types";
import ServiceHelper from "./service-helper";
import { CustomerDisplayResponse } from "@parksandresorts/webapiproxy-types";

export const ParkFoodService = {
  getQueueStatusForWeb(terminalIds: number[]): Promise<Array<CustomerDisplayWeb>> {
    return this.getQueueStatus(terminalIds).then((response) => {
      return response.customerDisplays.map((display) => mapCustomerDisplayApiToCustomerDisplayWeb(display));
    });
  },

  getQueueStatus(terminalIds: number[]): Promise<CustomerDisplayResponse> {
    return ServiceHelper.fetchGet(`parkfood/queue/${terminalIds}`);
  },

  getRandomQueueStatus(terminalId) {
    return ServiceHelper.fetchGet(
      `parkfood/randomqueue/${terminalId}`,
      null,
      "https://prs-cdp-dev-webapiproxy.azurewebsites.net/api/test93/",
    );
  },
};
