import { CustomerDisplayWeb } from "@/core/types/park-food-types";
import { CustomerDisplayItem, GlkrConfigDisplayType, GlkrConfigLimitType } from "@parksandresorts/webapiproxy-types";

export const mapCustomerDisplayApiToCustomerDisplayWeb = (
  customerDisplayApi: CustomerDisplayItem,
): CustomerDisplayWeb => {
  const allDisplayLabels = customerDisplayApi.displayLabels ?? [];
  const allLimitsReached = customerDisplayApi.limitsReached ?? [];

  const displayForWeb = allDisplayLabels.find((displayLabel) => displayLabel.displayType === GlkrConfigDisplayType.WEB);
  const waitTimeLabelWeb = displayForWeb ? displayForWeb.label : null;
  const approximateWaitTime = displayForWeb ? displayForWeb.approximateWaitTime : null;

  const shouldWarnForLongQueue = allLimitsReached.includes(GlkrConfigLimitType.DISPLAY_WEB_LONG_QUEUE_WARNING);
  const shouldStopWebOrders = allLimitsReached.includes(GlkrConfigLimitType.STOP_WEB_ORDERS);

  const newCustomerDisplayItem: CustomerDisplayWeb = {
    terminalId: customerDisplayApi.terminalId,
    preparingOrders: customerDisplayApi.preparingOrders,
    readyForDeliveryOrders: customerDisplayApi.readyForDeliveryOrders,
    waitTimeLabelWeb,
    approximateWaitTime,
    shouldWarnForLongQueue,
    shouldStopWebOrders,
  };

  return newCustomerDisplayItem;
};
