import { useMemo } from "react";

type Primitive = string | number | boolean | null | undefined;

type PrimitiveKeys<T> = { [K in keyof T]: T[K] extends Primitive ? K : never }[keyof T];

/**
 * useOrderedKeys picks the specified keys from the object, ensures key order, and memoizes the result
 *
 * The new object will return the keys in a consistent order, which is useful when the order of keys matters, and
 * enables memoization. We only allow keys of properties that are of primitive types, for simplicity.
 *
 * This hook will return a new object only when one of the following happens:
 * 1. the values of the picked keys change
 * 2. a key is added or removed from the object (a variant of the previous case)
 * 3. the order of the keys in the keyOrder array changes
 * 4. a key is added or removed from the keyOrder array (a variant of the previous case)
 *
 * @param obj The object from which to pick the keys. Does not need to be memoized beforehand.
 * @param keyOrder An array of keys which values are primitives
 * @returns a memoized object with the keys in the order specified in the keyOrder array.
 */
export function useOrderedKeys<T extends Partial<Record<string, unknown>>, K extends PrimitiveKeys<T>>(
  obj: T,
  keyOrder: Array<K>,
): Pick<typeof obj, K> {
  // track both existence and value of the keys, to trigger re-evaluation when a key is added or removed from the object
  const values = keyOrder.map((key) => [key in obj, obj[key]]);

  // Though stringifying is slightly expensive, it is easy to reason about, and fairly cheap enough when we limit
  // ourselves to primitive values
  const keyOrderString = JSON.stringify(keyOrder);
  const valuesString = JSON.stringify(values);

  return useMemo(() => {
    const orderedObj = {} as Pick<typeof obj, K>;
    for (const key of keyOrder) {
      // make sure we omit keys that are not present in the object, since we allow partial objects as input
      if (key in obj) {
        orderedObj[key] = obj[key];
      }
    }
    return orderedObj;
    // intentionally omit obj and keyOrder from the dependencies to avoid unnecessary re-renders:
    // * obj is not included because we only care about when the picked values change (tracked via valuesString)
    // * keyOrder is not included because we use keyOrderString as a substitute
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [keyOrderString, valuesString]);
}
