import { useState, useEffect, useCallback, useMemo } from "react";
import { useIsParkOpenNow } from "@/core/hooks/opening-hours-hooks";
import { CustomerDisplayItem } from "@parksandresorts/webapiproxy-types";
import { ParkFoodService, QueueTimesService } from "../services";
import { useQuery } from "@tanstack/react-query";
import { QueueTimeQueryParams } from "../services/queue-time-service";
import { useOrderedKeys } from "./use-ordered-keys";

type FetchQueueTimeOptions = QueueTimeQueryParams & {
  /** Used to automatically refetch queue times at a specified interval (in milliseconds). Will not refetch if omitted or zero */
  updateInterval?: number;
  /** Set to false to disable fetching. Defaults to true. */
  enabled?: boolean;
};

export function useFetchAllQueueTimes(options: FetchQueueTimeOptions) {
  const queryParams = useOrderedKeys(options, ["plcId", "includeEvents", "includeHideForWeb"]);

  const queueTimesResult = useQuery({
    queryKey: ["queueTimes", queryParams],
    queryFn: () => QueueTimesService.getQueueTimes(queryParams),
    refetchInterval: options.updateInterval || false,
    enabled: options.enabled ?? true,
  });

  useEffect(() => {
    if (queueTimesResult.error) {
      console.log("Failed to fetch queue times: ", queueTimesResult.error);
    }
  }, [queueTimesResult.error]);

  return queueTimesResult;
}

export function useFetchQueueTime(rideId: number, options: Omit<FetchQueueTimeOptions, "plcId">) {
  const { data: allQueueTimes } = useFetchAllQueueTimes({ ...options, plcId: rideId });

  return allQueueTimes?.find((item) => item.attractionId === rideId);
}

/**
 * Check if conditions are met to display ride queue times
 * @param enableRideQueueTimesUrlKey Optional string to check if it exists in current URL
 * @returns true if conditions are met to display ride queue times
 */
export const useDisplayAttractionQueueTime = (enableRideQueueTimesUrlKey: string | null = null) => {
  const isParkOpenNow = useIsParkOpenNow();

  return useMemo(() => {
    if (typeof window === "undefined") return false;

    const checkPassed =
      !enableRideQueueTimesUrlKey ||
      window.location.href.toLowerCase().includes(enableRideQueueTimesUrlKey.toLowerCase());

    return checkPassed && isParkOpenNow;
  }, [isParkOpenNow, enableRideQueueTimesUrlKey]);
};

export function useParkFoodWaitTimes(terminalIds: number[], updateIntervalMs = 10_000) {
  const [foodWaitTimes, setFoodWaitTimes] = useState<CustomerDisplayItem[] | undefined>(undefined);

  const fetchWaitTimes = useCallback(async () => {
    try {
      const response = await ParkFoodService.getQueueStatus(terminalIds);
      const foodWaitTimes = response.customerDisplays.filter((item) => item.terminalId !== 0);
      setFoodWaitTimes(foodWaitTimes);
    } catch (err) {
      console.log("Fetch food wait times failed: ", err);
    }
  }, [terminalIds]);

  useEffect(() => {
    fetchWaitTimes();

    const interval = setInterval(() => {
      fetchWaitTimes();
    }, updateIntervalMs);

    return () => {
      clearInterval(interval);
    };
  }, [fetchWaitTimes, terminalIds, updateIntervalMs]);

  return foodWaitTimes;
}
