import { QueueTimesResponse } from "@/core/types/services/queue-times-service-types";
import ServiceHelper from "./service-helper";

export type QueueTimeQueryParams = {
  /**
   * Commonly referred to as `attractionId`, but named `plcId` here.
   * If passed, it will return an array containing at most one item/attraction.
   */
  plcId?: number;
  /** If true, the endpoint will return values for event-days, which are not public by default */
  includeEvents?: boolean;
  /**
   * If true, the endpoint will include values that are hidden for the public web.
   *
   * This should only be used for views/blocks that are not public, such as queue-time overviews in the park.
   */
  includeHideForWeb?: boolean;
};
export const QueueTimesService = {
  getQueueTimes(optionalQueryParams: QueueTimeQueryParams = {}) {
    const queryString = new URLSearchParams(optionalQueryParams as Record<string, string>).toString();
    return ServiceHelper.fetchGet<QueueTimesResponse>(`/QueueTimes/?${queryString}`);
  },
};
